1   .visible .entry Add(
2       .param .u64 Add_param_0,
3       .param .u64 Add_param_1,
4       .param .u64 Add_param_2
5   ){
6       .reg .b32 %r<7>;
7       .reg .b64 %rd<4>;
8   
9       ld.param.u64    %rd1, [Add_param_0];
10      ld.param.u64    %rd2, [Add_param_1];
11      ld.param.u64    %rd3, [Add_param_2];
12  
13      ld.global.u32   %r4, [%rd1];
14      ld.global.u32   %r5, [%rd2];
15  
16      mov.u32         %r1, %clock;
17      add.u32         %r6, %r4, %r5;
18      mov.u32         %r2, %clock;
19      sub.s32         %r3, %r2, %r1;
20  
21      st.global.u32   [%rd3], %r3;
22  
23      ret;
24  }



### 说明：
- 所有行号（1–24）已保留在左侧。
- 原始缩进使用空格保持对齐（如第2–4行参数缩进，第6–7行寄存器声明缩进等）。
- 指令关键字（如 `ld.param.u64`, `mov.u32`, `ret` 等）与操作数之间的空格完全保留。
- 注释符号 `%` 和寄存器命名（如 `%r<7>`, `%rd<4>`）原样保留。
- 特殊标记如 `.visible`, `.entry`, `.param`, `.reg`, `.global` 等均按原文呈现。
- 空行（如第8、12、15、20、22行）也予以保留以维持视觉结构。

此格式可直接用于支持语法高亮的 Markdown 渲染器（如 GitHub、GitLab、Typora 等），并准确反映原始 PTX 汇编代码的结构与细节。

1 .visible .entry globalMem(
2     .param .u64 globalMem_param_0,
3     .param .u64 globalMem_param_1,
4 ){
5     .reg .b32   %r<5>;
6     .reg .b64   %rd<3>;
7 
8     ld.param.u64    %rd1, [globalMem_param_0];
9     ld.param.u64    %rd2, [globalMem_param_1];
10 
11    mov.u32         %r1, %clock;
12    ld.global.u32   %r4, [%rd1 + 4];
13    mov.u32         %r2, %clock;
14    sub.s32         %r3, %r2, %r1;
15 
16    mov.u32         %r1, %clock;
17    ld.global.u32   %r5, [%rd1 + 8];
18    mov.u32         %r2, %clock;
19    sub.s32         %r4, %r2, %r1;
20 
21    st.global.u32   [%rd2], %r3;
22    st.global.u32   [%rd2 + 4], %r4;
23    ret;
24 }



### 说明：
- 保留了原始代码的**行号**（1–24），每行以数字开头。
- 保留了**缩进结构**：函数体内部语句相对于 `.entry` 声明有适当缩进（使用空格或制表符模拟原图视觉层级）。
- 保留了**指令关键字颜色语义**（如 `ld`, `mov`, `sub`, `st`, `ret` 等为紫色；寄存器如 `%r`, `%rd` 为蓝色；类型如 `.u64`, `.u32` 为绿色；注释/符号如 `[ ]`, `,`, `;` 保持黑色）——在纯 Markdown 中无法直接渲染颜色，但通过语法高亮块可间接体现结构。
- 保留了**特殊标记**如 `<5>`, `<3>` 表示寄存器数组大小。
- 保留了**空行**（第7、10、15、20行）用于逻辑分组。
- 最后一行闭合大括号 `}` 单独成行，与起始 `{` 对齐。

此格式可用于文档记录、代码审查或进一步处理，完全忠实于原始图像内容。
